144	 * 주문 명령 컨트롤러 (Kafka 비동기 처리)
145	 */
146	@RestController
147	@RequestMapping("/orders")
148	@RequiredArgsConstructor
149	@Slf4j
150	@Validated
151	public class OrderCommandController {
152	
153	    private final OrderEventProducer orderEventProducer; // 기존 OrderCommandService 대신 Kafka Producer 사용
154	
155	    /**
156	     * 주문의 결제 및 배송 정보를 처리합니다.
157	     * ⭐ 전체 처리를 Kafka로 비동기 처리하고 즉시 응답
158	     *
159	     * @param orderId 주문 ID
160	     * @param requestDto 결제 및 배송 요청 정보
161	     * @return 처리 진행 상태 응답
162	     * @throws OrderAccessDeniedException 주문에 대한 접근 권한이 없는 경우
163	     * @throws InvalidPaymentShipmentDataException 결제 및 배송 정보가 유효하지 않은 경우
164	     */
165	    @PostMapping("/{orderId}/process-payment-shipment")
166	    public ResponseEntity<ResponseDto<Map<String, Object>>> processPaymentAndShipment(
167	            @PathVariable("orderId") Long orderId,
168	            @RequestBody @Valid PayAndShipmentRequestDto requestDto
169	    ) {
170	        // 사용자 이메일 추출 및 검증
171	        String email = SecurityUtils.extractAndValidateEmailForOrder("결제 및 배송 처리");
172	
173	        log.info("사용자 [{}]가 주문(ID: {})의 결제 및 배송 처리를 요청합니다.", email, orderId);
174	
175	        try {
176	            // Kafka로 비동기 주문 처리 이벤트 발행
177	            orderEventProducer.sendOrderProcessingEvent(orderId, email, requestDto);
178	
179	            // 즉시 응답 데이터 생성
180	            Map<String, Object> responseData = new HashMap<>();
181	            responseData.put("orderId", orderId);
182	            responseData.put("status", "PROCESSING");
183	            responseData.put("message", "주문이 접수되었습니다. 결제를 처리하고 있습니다.");
184	            responseData.put("estimatedProcessingTime", "1-3분");
185	            responseData.put("websocketTopic", "/topic/order/" + orderId);
186	            responseData.put("statusCheckUrl", "/api/orders/" + orderId + "/status");
187	
188	            log.info("주문 처리 이벤트 발행 완료: 주문ID={}, 사용자={}", orderId, email);
189	
190	            // 202 Accepted 응답 (처리 중임을 명시)
191	            return ResponseEntity.status(HttpStatus.ACCEPTED)
192	                    .body(ResponseDto.success(responseData, "주문 처리가 시작되었습니다. 처리 완료 시 알림을 받으실 수 있습니다."));
193	
194	        } catch (Exception e) {
195	            log.error("주문 처리 이벤트 발행 실패: 주문ID={}, 사용자={}, 오류={}", orderId, email, e.getMessage(), e);
196	
197	            // 실패 시 즉시 오류 응답
198	            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
199	                    .body(ResponseDto.error("ORDER_PROCESSING_FAILED",
200	                            "주문 처리 요청 중 오류가 발생했습니다: " + e.getMessage()));
201	        }
202	    }
