225	//
226	//        return ResponseEntity.ok(ResponseDto.success(null, "결제 및 배송 처리가 성공적으로 완료되었습니다."));
227	//    }
228	
229	    /**
230	     * 주문 처리 취소 API (선택적)
231	     * 처리 중인 주문을 취소할 수 있도록 제공
232	     */
233	    @PostMapping("/{orderId}/cancel")
234	    public ResponseEntity<ResponseDto<Map<String, Object>>> cancelOrderProcessing(@PathVariable Long orderId) {
235	        String email = SecurityUtils.extractAndValidateEmailForOrder("주문 처리 취소");
236	
237	        log.info("주문 처리 취소 요청: 주문ID={}, 사용자={}", orderId, email);
238	
239	        try {
240	            // TODO: 취소 로직 구현 (처리 상태에 따라 취소 가능 여부 판단)
241	
242	            Map<String, Object> cancelData = new HashMap<>();
243	            cancelData.put("orderId", orderId);
244	            cancelData.put("status", "CANCELLED");
245	            cancelData.put("message", "주문 처리가 취소되었습니다.");
246	
247	            return ResponseEntity.ok(ResponseDto.success(cancelData, "주문 처리 취소 성공"));
248	
249	        } catch (Exception e) {
250	            log.error("주문 처리 취소 실패: 주문ID={}, 사용자={}, 오류={}", orderId, email, e.getMessage(), e);
251	
252	            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
253	                    .body(ResponseDto.error("ORDER_CANCEL_FAILED",
254	                            "주문 처리 취소 중 오류가 발생했습니다: " + e.getMessage()));
255	        }
256	    }
